#!/usr/bin/env node
/** Research-only CLI override: Desktop owns this process and the official server it starts.
 * --config is generated by desktop-owned-runtime-feasibility.mjs in an isolated temp directory.
 * All non-server CLI operations pass through unchanged. No app package is modified.
 */
import { spawn } from 'node:child_process';
import { readFile, writeFile, appendFile } from 'node:fs/promises';
import { existsSync, createWriteStream } from 'node:fs';
import { createRequire } from 'node:module';
import { createInterface } from 'node:readline';
import net from 'node:net';

const args = process.argv.slice(2);
if (args.shift() !== '--config') throw new Error('Expected --config <research-config.json>');
const config = JSON.parse(await readFile(args.shift(), 'utf8'));
const require = createRequire(config.packagePath);
const WebSocket = require('ws');
const log = (event, details={}) => appendFile(config.logPath, JSON.stringify({at:Date.now(),event,pid:process.pid,ppid:process.ppid,...details})+'\n');
await log('cli_invocation',{args});
const index=args.indexOf('app-server');
const ordinaryServer=index>=0&&!['proxy','daemon','generate-ts','generate-json-schema','help'].includes(args[index+1]);
if (!ordinaryServer) {
  const child=spawn(config.binary,args,{stdio:'inherit',env:{...process.env,CODEX_CLI_PATH:config.binary}});
  child.on('exit',(code,signal)=>{if(signal)process.kill(process.pid,signal);else process.exit(code??1);});
  child.on('error',e=>{process.stderr.write(String(e)+'\n');process.exit(1);});
} else {
  if(existsSync(config.socketPath))throw new Error('Research socket already exists; refusing to replace it');
  const serverArgs=[...args,'--listen','unix://'+config.socketPath];
  const child=spawn(config.binary,serverArgs,{stdio:['ignore','pipe','pipe'],env:{...process.env,CODEX_CLI_PATH:config.binary}});
  const serverLog=createWriteStream(config.serverLogPath,{flags:'a'});
  child.stdout.pipe(serverLog,{end:false});child.stderr.pipe(serverLog,{end:false});
  const state={adapterPid:process.pid,desktopPid:process.ppid,serverPid:child.pid,socketPath:config.socketPath,serverArgs,startedAt:Date.now()};
  await writeFile(config.statePath,JSON.stringify(state,null,2));await log('server_spawned',state);
  let stopping=false,socket;
  async function shutdown(reason){
    if(stopping)return;stopping=true;await log('adapter_shutdown',{reason});
    socket?.close();child.kill('SIGTERM');
    setTimeout(()=>{if(child.exitCode===null&&child.signalCode===null)child.kill('SIGKILL');process.exit(0);},1500);
    child.once('exit',()=>process.exit(0));
  }
  process.on('SIGTERM',()=>shutdown('desktop_sigterm'));process.on('SIGINT',()=>shutdown('sigint'));
  child.on('error',e=>{process.stderr.write(String(e)+'\n');shutdown('server_error');});
  child.on('exit',(code,signal)=>{log('server_exit',{code,signal}).finally(()=>{if(!stopping){socket?.close();process.exit(code??1);}});});
  const queue=[];
  createInterface({input:process.stdin}).on('line',line=>{
    if(socket?.readyState===WebSocket.OPEN)socket.send(line);else queue.push(line);
    let message;try{message=JSON.parse(line);}catch{return;}
    if(['initialize','thread/start','thread/resume','turn/start'].includes(message.method))log('desktop_request',{method:message.method,threadId:message.params?.threadId,client:message.params?.clientInfo?.name});
  }).on('close',()=>shutdown('desktop_stdin_closed'));
  const deadline=Date.now()+15000;
  while(!existsSync(config.socketPath)&&Date.now()<deadline&&child.exitCode===null&&child.signalCode===null)await new Promise(r=>setTimeout(r,50));
  if(!existsSync(config.socketPath))throw new Error('Desktop-owned server listener did not start');
  socket=new WebSocket('ws://localhost/rpc',{createConnection:()=>net.createConnection(config.socketPath)});
  socket.on('open',()=>{log('desktop_bridge_connected');for(const line of queue)socket.send(line);queue.length=0;});
  socket.on('message',data=>process.stdout.write(data.toString()+'\n'));
  socket.on('error',e=>{process.stderr.write('Research bridge: '+e.message+'\n');shutdown('socket_error');});
  socket.on('close',()=>shutdown('socket_closed'));
}
